python3 -I - <<'EOF'
import json,os,glob,time,hashlib
fs=[f for f in glob.glob('./claude-502/**/canvas.json',recursive=True) if 'project' in f and 'e4519567' not in f and 'c1367e67' not in f and '/logo/' not in f]
snaps=[]
for f in fs:
    try: c=json.load(open(f))
    except: continue
    if len(c.get('boards',{}))<100: continue
    h=hashlib.md5(json.dumps({'b':sorted(c['boards']),'n':{k:v.get('text') for k,v in c['notes'].items()}},sort_keys=True).encode()).hexdigest()
    snaps.append((os.path.getmtime(f),h,f,c))
snaps.sort()
seen=set(); uniq=[]
for s in snaps:
    if s[1] in seen: continue
    seen.add(s[1]); uniq.append(s)
prev=None
for t,h,f,c in uniq:
    print('\n=====',time.strftime('%m-%d %H:%M',time.localtime(t)),len(c['boards']),'boards',f.split('/')[3][:8])
    if prev:
        pb,pn=prev['boards'],prev['notes']
        add=sorted(set(c['boards'])-set(pb)); rem=sorted(set(pb)-set(c['boards']))
        if add: print('  + boards:',add)
        if rem: print('  - boards:',rem)
        for k,n in c['notes'].items():
            if k not in pn: print('  + note',k,':',n['text'][:220].replace('\n',' '))
            elif pn[k].get('text')!=n.get('text'):
                print('  ~ note',k,':',n['text'][:220].replace('\n',' '))
        for k in pn:
            if k not in c['notes']: print('  - note',k,':',pn[k]['text'][:120])
    prev=c
EOF

